/**
 * Home page text (the pillar). Figures come from the kit; the state table and the group lists are
 * generated by HomePage.astro.
 */
import type { FAQ, Helpers } from '../lib/page-types';
import { KIT as K } from '../lib/kit';

const o = K.sum('US', 'ho')!;
const p = K.sum('US', 'pr')!;
const yo = K.yoy('US', 'ho');
const yp = K.yoy('US', 'pr');
const ro = K.ranked('ho');
const rp = K.ranked('pr');
const W = K.W;
const lastO = K.lastDone('US', 'ho')!;
const replO = K.replay(o.seasons.filter((x) => x.s !== o.season), o.last[1]);

export const VALUE = `What the site adds to the federal tables: this week's price for each state and fuel with the change on a week and on a year, the cost of filling your own tank (the propane fill limit applied), a winter budget scaled to your state's degree days, a check of a fixed-price offer against every winter since 2013-14, the days your tank will last, and the federal LIHEAP income ceiling for your household. Everything is computed in your browser from files dated to the week.`;

export const HOME = {
  title: 'Heating Oil, Propane Prices per Gallon Today by State 2026',
  description: `Heating oil and propane prices per gallon today, by state, from the federal survey, 2026-27: cost of a delivery, winter budget, lock-in check, LIHEAP limits.`,
  h1: 'Heating oil and propane prices per gallon today, state by state',
  intro: `Heating oil averaged ${K.ppg(o.last[1])} a gallon and propane ${K.ppg(p.last[1])} in the United States in the week of ${K.day(o.last[0])}, before tax. Choose your state and the gallons you order.`,
  resume: `Residential heating oil cost an average of ${K.ppg(o.last[1])} a gallon in the United States in the Energy Information Administration's survey of ${K.day(o.last[0])}, ${K.dir(yo, 'up', 'down')} ${yo === null ? '' : K.pct(Math.abs(yo), 0)} on the same week of 2025, and residential propane ${K.ppg(p.last[1])}, ${K.dir(yp, 'up', 'down')} ${yp === null ? '' : K.pct(Math.abs(yp), 0)}. State averages ran from ${K.ppg(K.price(ro.at(-1)!.code, 'ho')!)} in ${ro.at(-1)!.name} to ${K.ppg(K.price(ro[0].code, 'ho')!)} in ${ro[0].name} for heating oil, and from ${K.ppg(K.price(rp.at(-1)!.code, 'pr')!)} in ${rp.at(-1)!.name} to ${K.ppg(K.price(rp[0].code, 'pr')!)} in ${rp[0].name} for propane. At the national average, 150 gallons of heating oil cost ${K.usd(150 * o.last[1])}, and filling a 500-gallon propane tank from 30 % to the usual 80 % costs ${K.usd(250 * p.last[1])}. The EIA's winter outlook expects the average oil-heated home to spend ${K.usd(W.ho.US.spend.base)} from November to March and the average propane home ${K.usd(W.pr.US.spend.base)}. Prices exclude taxes and refresh every Wednesday from October to March; the lookup above gives your state's figure and the cost of your order.`,
  sources: ['eia_shopp', 'eia_ho_weekly', 'eia_pr_weekly', 'eia_wfo', 'nyserda_ho', 'noaa_hdd', 'acs_b25040', 'usc_8624', 'osha_lpg'],
  why: (h: Helpers) => `
<h2>What the weekly survey measures</h2>
<p>Every Monday from October through March, the EIA's State Heating Oil and Propane Program asks a sample of fuel dealers what they charge households for No. 2 heating oil and for propane. The averages come out on Wednesday, by state, by petroleum district and for the nation (${h.src('eia_shopp', 'EIA Heating Oil and Propane Update')}). They are prices per gallon, excluding taxes, and the EIA can revise the previous week when late reports arrive. This season the program covers ${ro.length} states for heating oil and ${rp.length} for propane: the oil states of the Northeast, the Mid-Atlantic and the upper Midwest, and a wider set for propane that reaches from Florida and Texas to the Rocky Mountains.</p>
<p>A state average is a yardstick, not your price. Your dealer's quote depends on the size of the order, the type of account (automatic delivery, will-call, cash on delivery), any service plan and, for propane, whether you own or lease the tank. What the average does tell you is where the market is this week, how it has moved, and whether a quote is in the normal range.</p>
<h2>This week in context</h2>
<p>The national heating oil price ${K.dir(K.wow('US', 'ho'), 'rose', 'fell', 'held')} ${K.wow('US', 'ho') === null ? '' : K.ppg(Math.abs(K.wow('US', 'ho')!))} from the week before. Last winter it averaged ${K.ppg(lastO.avg!)} from November to March, with a high of ${K.ppg(lastO.max[1])} on ${K.day(lastO.max[0])}. The highest week since October 2013 is ${K.ppg(o.record[1])}, in the week of ${K.day(o.record[0])}. The EIA's outlook of October 2026 forecasts ${K.ppg(W.ho.US.price.base)} a gallon on average for this winter (${h.a('heating-oil-price-forecast', 'the forecast in detail')}).</p>
<p>Propane moves on a different rhythm. The national propane average this week is ${K.ppg(p.last[1])}, against a winter average of ${K.ppg(K.lastDone('US', 'pr')!.avg!)} last season. Its wholesale price was ${p.wholesale ? K.ppg(p.wholesale) : 'not published'}, so most of what a household pays goes to delivery and the dealer's costs rather than to the gas itself. That is also why propane prices differ so much between states, and heating oil so little.</p>
${h.mini('fill', { t: 'Cost to fill your tank at this week\'s price', p: ['fuel', 'gauge'], d: { st: 'NY', fuel: 'ho', tank: 275 }, c: 'Open the tank fill calculator' })}
<h2>From a price per gallon to a winter's bill</h2>
<p>Most people who search for heating oil prices want one of three numbers. The first is the cost of the next delivery: gallons needed times the price, which depends on your tank and your gauge. The ${h.a('heating-oil-tank-fill-cost', 'oil tank calculator')} and the ${h.a('propane-tank-fill-cost', 'propane tank calculator')} do it; the propane one applies the federal limit on how full a tank may be (${h.src('osha_lpg', '29 CFR 1910.110')}), which several price pages ignore.</p>
<p>The second is the cost of the winter. Fuel use follows heating degree days, and the EIA publishes the gallons an average household burns in each region over a normal winter: ${K.gal(W.ho.US.gal.base)} of heating oil, ${K.gal(W.pr.US.gal.base)} of propane. The ${h.a('winter-heating-budget', 'winter budget')} scales them to your state with NOAA's normals (${h.src('noaa_hdd', 'NOAA degree days')}) and multiplies by this week's price, or uses your own gallons from last winter.</p>
<p>The third is a decision: sign the fixed-price or prebuy contract a dealer offers, or pay the weekly price. Over the ${replO.n} winters on file, the national heating oil price averaged above its mid-October level from November to March in ${replO.up}. The ${h.a('lock-in-or-wait', 'lock-in check')} replays every winter of your state against the price you are offered and gives the break-even.</p>
<h2>Where oil and propane heat American homes</h2>
<p>The EIA counts ${K.num(W.households.US.ho)} households heating mainly with heating oil or kerosene this winter, ${K.num(W.households.Northeast.ho)} of them in the Northeast, and ${K.num(W.households.US.pr)} heating with propane, spread far more evenly: ${K.num(W.households.Midwest.pr)} in the Midwest, ${K.num(W.households.South.pr)} in the South, ${K.num(W.households.Northeast.pr)} in the Northeast and ${K.num(W.households.West.pr)} in the West. The Census Bureau's count by state (${h.src('acs_b25040', 'American Community Survey, Table B25040')}) shows the same map: oil concentrated in the Northeast, propane present in every region. Each state page gives the number of homes on each fuel next to the prices.</p>
<p>New York has a second source. NYSERDA publishes weekly averages for Long Island, New York City, the Hudson Valley and the upstate regions on the state's open data portal (${h.src('nyserda_ho', 'NYSERDA heating oil prices')}), and the ${h.a('long-island-heating-oil-prices', 'Long Island page')} compares them.</p>
`,
  sections: (h: Helpers) => [
    {
      title: 'Why heating oil prices differ between states',
      html: `<p>Heating oil reaches each state from coastal and inland terminals at a wholesale price that differs little across a region. Dealers then add the cost of storage, trucks, drivers, credit, service plans and their margin. The EIA publishes both prices for most oil states, so the dealer spread can be measured: this week it runs from ${K.ppg(Math.min(...ro.map((s) => K.spread(s.code, 'ho') ?? 99)))} to ${K.ppg(Math.max(...ro.map((s) => K.spread(s.code, 'ho') ?? 0)))} a gallon. The order of the states changes slowly from week to week; the level of the whole table moves with the wholesale market for distillates, which also drives diesel (${h.src('eia_heating_oil', 'EIA, heating oil explained')}). The ${h.a('heating-oil-prices', 'state table for heating oil')} ranks them with the spread.</p>`,
    },
    {
      title: 'Why propane can cost twice as much one state over',
      html: `<p>Wholesale propane costs about the same everywhere in a region. The retail price adds delivery to scattered tanks, tank rental or maintenance and the dealer's margin, and that added part ranges widely: this week the state averages run from ${K.ppg(K.price(rp.at(-1)!.code, 'pr')!)} to ${K.ppg(K.price(rp[0].code, 'pr')!)}. A household in a dear state gains most from knowing the state average, because the quotes it receives can be far from it in either direction. The ${h.a('propane-prices', 'state table for propane')} gives every surveyed state with last winter's average.</p>`,
    },
    {
      title: 'Taxes, fees and what the average leaves out',
      html: `<p>The EIA excludes taxes so that states compare on the same basis. Your bill can add a state or local tax, an environmental fee, a small-delivery charge, an after-hours charge, a tank rental or a service plan. Heating oil carries no road fuel tax: it is dyed red to show that it is exempt from the federal, state and local taxes on fuel for vehicles. Every calculator on this site has an option to add a tax rate and, for the price, to type the one your dealer quotes.</p>`,
    },
    {
      title: 'When the numbers change',
      html: `<p>The EIA released the current figures on ${K.day(K.L.release_date)} and plans the next release for ${K.day(K.L.next_release)}. A script reads the files on the day of release and rebuilds the site; if the EIA's server does not answer, the previous week stays online with its own date, and nothing is estimated in its place. From April to September the survey stops: the pages then show the last week of March until the first October release. The winter forecast follows the EIA's monthly outlook, the degree days and the household counts change once a year.</p>`,
    },
    {
      title: 'Help with heating bills',
      html: `<p>The Low Income Home Energy Assistance Program helps households pay for heating, including oil and propane deliveries. Federal law caps the income a state may use at the greater of 150 % of the poverty guideline and 60 % of the state median income (${h.src('usc_8624', '42 U.S.C. 8624')}); for a household of three that ceiling is ${K.usd(K.liheap('PA', 3))} a year in Pennsylvania and ${K.usd(K.liheap('ME', 3))} in Maine for fiscal year 2027. States may set lower limits. The ${h.a('liheap-income-limits', 'LIHEAP calculator')} gives the ceiling for every state and household size.</p>`,
    },
    {
      title: 'Oil or propane: comparing the heat, not the gallon',
      html: `<p>A gallon of heating oil holds ${K.num(K.P.btu.oil)} Btu and a gallon of propane ${K.num(K.P.btu.propane)}, according to the EIA (${h.src('eia_btu', 'Btu explained')}). Comparing prices per gallon therefore flatters propane. The fair comparison is the cost of a million Btu delivered into the home after the efficiency of the boiler or furnace. At this week's national averages and ENERGY STAR minimum efficiencies, oil heat costs ${K.usd(K.perMBtu({ price: o.last[1], btu: K.P.btu.oil, efficiency: K.P.efficiency.oil }))} and propane heat ${K.usd(K.perMBtu({ price: p.last[1], btu: K.P.btu.propane, efficiency: K.P.efficiency.propane }))} per million Btu. The ${h.a('heating-oil-vs-propane', 'comparison page')} does it state by state, with electric resistance heat for reference.</p>`,
    },
  ],
  faqs: [
    { q: 'What is the price of heating oil per gallon today?', a: `The latest federal survey, for the week of ${K.day(o.last[0])}, puts the U.S. residential average at ${K.ppg(o.last[1])} a gallon excluding taxes. State averages ranged from ${K.ppg(K.price(ro.at(-1)!.code, 'ho')!)} to ${K.ppg(K.price(ro[0].code, 'ho')!)}. Prices are surveyed each Monday and published each Wednesday from October to March; the lookup at the top gives your state's figure.` },
    { q: 'Why are heating oil prices so high this year?', a: `The retail price follows the wholesale price of distillate fuel, which this week stood at ${o.wholesale ? K.ppg(o.wholesale) : 'a level the EIA did not publish'} a gallon nationally against ${K.ppg(o.last[1])} at retail. ${yo === null ? '' : `The national retail price is ${K.dir(yo, 'up', 'down')} ${K.pct(Math.abs(yo), 0)} on a year.`} The EIA's outlook explains its forecast in its monthly Short-Term Energy Outlook; the forecast page summarizes it.` },
    { q: 'Is propane cheaper than heating oil?', a: `Per gallon it usually is, but a gallon of propane carries ${K.pct(K.P.btu.propane / K.P.btu.oil, 0)} of the heat of a gallon of oil. Per unit of heat delivered, the answer depends on the state and the week. The comparison page computes the cost of a million Btu from both fuels in every state surveyed for both, with your equipment's efficiency.` },
    { q: 'When does the EIA publish heating oil prices?', a: `On Wednesday of each week from October through March, for prices collected on the Monday. The current release is dated ${K.day(K.L.release_date)} and the next one is planned for ${K.day(K.L.next_release)}. Between April and September the survey stops, and this site keeps the last published week on display with its date.` },
    { q: 'Does this site sell heating oil or pass my details to dealers?', a: 'No. Heat Fuel Prices is an independent publisher of price data and calculators. It sells no fuel, lists no dealer, takes no commission and asks for no ZIP code, address, phone number or e-mail. The calculators run in your browser; what you type is not sent anywhere.' },
    { q: 'How much does it cost to heat a house with oil for a winter?', a: `The EIA's outlook puts the average oil-heated household at ${K.gal(W.ho.US.gal.base)} and ${K.usd(W.ho.US.spend.base)} from November to March in a normal winter. A home in a cold state or with poor insulation burns more. The winter budget calculator scales the gallons to your state's degree days and applies this week's state price.` },
  ] as FAQ[],
};
